Lemma AG_B : forall i E1 A1 M1 m1 (Mx M2 : mem) scr Wc, (2 <= i < PSO.NCUT)%nat -> AAMB I i E1 A1 M1 m1 ->
  CHA.ahpres L ar ((sbI i E1, scapI i E1) :: LBV) (CHA.curF FF sp PSO.FFS i E1) (sp + PSO.CSP) scr Wc Mx M2 -> 672 + scr <= 17600 ->
